export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  sourcePath: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  url: string;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
}

export interface TagIndex {
  tag: string;
  pages: Page[];
}

export interface BuildResult {
  pages: Page[];
  tags: TagIndex[];
  errors: string[];
}

import { readFile, writeFile, mkdir, readdir, copyFile, stat } from "node:fs/promises";
import { join, dirname, extname, relative, basename } from "node:path";

export async function readTextFile(path: string): Promise<string> {
  return readFile(path, "utf-8");
}

export async function writeTextFile(path: string, content: string): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, content, "utf-8");
}

export async function ensureDir(dir: string): Promise<void> {
  await mkdir(dir, { recursive: true });
}

export async function* walkDir(dir: string): AsyncGenerator<string> {
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      yield* walkDir(full);
    } else {
      yield full;
    }
  }
}

export async function copyDir(src: string, dest: string): Promise<void> {
  const entries = await readdir(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = join(src, entry.name);
    const destPath = join(dest, entry.name);
    if (entry.isDirectory()) {
      await copyDir(srcPath, destPath);
    } else {
      await mkdir(dirname(destPath), { recursive: true });
      await copyFile(srcPath, destPath);
    }
  }
}

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

export function formatDate(date: Date): string {
  return date.toISOString().split("T")[0];
}

export function parseDate(raw: string): Date {
  const d = new Date(raw);
  if (isNaN(d.getTime())) throw new Error(`Invalid date: ${raw}`);
  return d;
}

export function pathToUrl(filePath: string, sourceDir: string): string {
  const rel = relative(sourceDir, filePath);
  const parsed = basename(rel, extname(rel));
  if (parsed === "index") {
    const dirPart = dirname(rel);
    return dirPart === "." ? "/" : `/${dirPart}/`;
  }
  return `/${parsed}/`;
}

import yaml from "js-yaml";
import type { Frontmatter } from "./types.js";

const SEP = "---";
const SEP_RE = /^---\s*$/m;

export interface ParsedMarkdown {
  frontmatter: Frontmatter;
  body: string;
}

export function parseFrontmatter(raw: string): ParsedMarkdown {
  const trimmed = raw.trimStart();
  if (!trimmed.startsWith(SEP)) {
    return { frontmatter: { title: "Untitled" }, body: raw };
  }

  const firstNewline = trimmed.indexOf("\n");
  const rest = trimmed.slice(firstNewline + 1);
  const endIdx = rest.indexOf("\n---");

  if (endIdx === -1) {
    return { frontmatter: { title: "Untitled" }, body: raw };
  }

  const yamlBlock = rest.slice(0, endIdx);
  const bodyStart = rest.indexOf("\n", endIdx + 4);
  const body = bodyStart === -1 ? "" : rest.slice(bodyStart + 1);

  let frontmatter: Frontmatter;
  try {
    frontmatter = (yaml.load(yamlBlock) as Frontmatter) ?? { title: "Untitled" };
  } catch {
    frontmatter = { title: "Untitled" };
  }

  if (!frontmatter.title) {
    frontmatter.title = "Untitled";
  }

  // Normalize tags
  if (frontmatter.tags && !Array.isArray(frontmatter.tags)) {
    frontmatter.tags = [String(frontmatter.tags)];
  }
  if (Array.isArray(frontmatter.tags)) {
    frontmatter.tags = frontmatter.tags.map(t => String(t).trim().toLowerCase()).filter(Boolean);
  }

  return { frontmatter, body };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

marked.setOptions({
  gfm: true,
  breaks: false,
});

export function markdownToHtml(markdown: string): string {
  const result = marked.parse(markdown);
  if (typeof result === "string") return result;
  return result.then ? "" : String(result);
}

import Handlebars from "handlebars";
import { readFile, readdir } from "node:fs/promises";
import { join, extname, relative, basename } from "node:path";

export interface TemplateEngine {
  render(template: string, data: Record<string, unknown>): string;
  renderPage(
    pageTemplate: string,
    data: Record<string, unknown>,
    layout?: string
  ): string;
}

let handlebars: typeof Handlebars;

export async function createEngine(templateDir: string): Promise<TemplateEngine> {
  const instance = Handlebars.create();
  handlebars = instance;

  // Load partials from partials/ subdirectory
  const partialsDir = join(templateDir, "partials");
  try {
    const partialFiles = await readdir(partialsDir, { withFileTypes: true });
    for (const entry of partialFiles) {
      if (entry.isFile() && extname(entry.name) === ".hbs") {
        const name = basename(entry.name, ".hbs");
        const content = await readFile(join(partialsDir, entry.name), "utf-8");
        instance.registerPartial(name, content);
      }
    }
  } catch {
    // No partials directory — that's fine
  }

  // Load templates from templateDir
  const templates = new Map<string, string>();
  try {
    const templateFiles = await readdir(templateDir, { withFileTypes: true });
    for (const entry of templateFiles) {
      if (entry.isFile() && extname(entry.name) === ".hbs" && entry.name !== "layout.hbs") {
        const name = basename(entry.name, ".hbs");
        const content = await readFile(join(templateDir, entry.name), "utf-8");
        templates.set(name, instance.compile(content)({}));
        instance.registerPartial(name, content);
      }
    }
  } catch {
    // No templates — that's fine
  }

  // Load layout if present
  let layoutSource = "";
  try {
    layoutSource = await readFile(join(templateDir, "layout.hbs"), "utf-8");
  } catch {
    // No layout
  }

  return {
    render(template: string, data: Record<string, unknown>): string {
      const compiled = instance.compile(template, { noEscape: true });
      return compiled(data);
    },

    renderPage(
      pageTemplate: string,
      data: Record<string, unknown>,
      layout?: string
    ): string {
      const compiledPage = instance.compile(pageTemplate);
      const body = compiledPage(data);

      const layoutTemplate = layout || layoutSource;
      if (!layoutTemplate) return body;

      const compiledLayout = instance.compile(layoutTemplate);
      return compiledLayout({ ...data, body: new instance.SafeString(body) });
    },
  };
}

// For tests — don't need templateDir
export function createTestEngine(
  partials?: Record<string, string>,
  layout?: string
): TemplateEngine {
  const instance = Handlebars.create();
  handlebars = instance;

  if (partials) {
    for (const [name, content] of Object.entries(partials)) {
      instance.registerPartial(name, content);
    }
  }

  return {
    render(template: string, data: Record<string, unknown>): string {
      const compiled = instance.compile(template, { noEscape: true });
      return compiled(data);
    },

    renderPage(
      pageTemplate: string,
      data: Record<string, unknown>,
      pageLayout?: string
    ): string {
      const compiledPage = instance.compile(pageTemplate);
      const body = compiledPage(data);

      const effectiveLayout = pageLayout || layout;
      if (!effectiveLayout) return body;

      const compiledLayout = instance.compile(effectiveLayout);
      return compiledLayout({ ...data, body: new instance.SafeString(body) });
    },
  };
}

import type { Page, TagIndex } from "./types.js";

export function buildTagIndexes(pages: Page[]): TagIndex[] {
  const tagMap = new Map<string, Page[]>();

  for (const page of pages) {
    if (page.frontmatter.draft) continue;
    const tags = page.frontmatter.tags;
    if (!tags || tags.length === 0) continue;

    for (const tag of tags) {
      const existing = tagMap.get(tag) ?? [];
      existing.push(page);
      tagMap.set(tag, existing);
    }
  }

  const indexes: TagIndex[] = [];
  for (const [tag, taggedPages] of tagMap.entries()) {
    taggedPages.sort((a, b) => {
      const da = a.frontmatter.date ?? "";
      const db = b.frontmatter.date ?? "";
      return db.localeCompare(da);
    });
    indexes.push({ tag, pages: taggedPages });
  }

  indexes.sort((a, b) => a.tag.localeCompare(b.tag));
  return indexes;
}

import type { Page, SiteConfig } from "./types.js";
import { formatDate, parseDate } from "./utils.js";

function escapeXml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export function generateRss(pages: Page[], config: SiteConfig): string {
  const published = pages
    .filter(p => !p.frontmatter.draft && p.frontmatter.date)
    .sort((a, b) => {
      const da = parseDate(a.frontmatter.date!);
      const db = parseDate(b.frontmatter.date!);
      return db.getTime() - da.getTime();
    })
    .slice(0, 20);

  const items = published
    .map(p => {
      const date = parseDate(p.frontmatter.date!);
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(config.siteUrl + p.url)}</link>
      <guid>${escapeXml(config.siteUrl + p.url)}</guid>
      <pubDate>${date.toUTCString()}</pubDate>
      <description>${escapeXml(p.frontmatter.title)}</description>
    </item>`;
    })
    .join("\n");

  const now = new Date().toUTCString();

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(config.siteUrl)}</link>
    <description>${escapeXml(config.siteTitle)}</description>
    <language>en</language>
    <lastBuildDate>${now}</lastBuildDate>
    <atom:link href="${escapeXml(config.siteUrl + "/feed.xml")}" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>
`;
}

import { join, extname, dirname, relative } from "node:path";
import { readFile } from "node:fs/promises";
import type { Page, SiteConfig, BuildResult } from "./types.js";
import { parseFrontmatter } from "./frontmatter.js";
import { markdownToHtml } from "./markdown.js";
import { createEngine, type TemplateEngine } from "./templates.js";
import { buildTagIndexes } from "./tags.js";
import { generateRss } from "./rss.js";
import { walkDir, writeTextFile, copyDir, ensureDir, pathToUrl } from "./utils.js";

export async function build(config: SiteConfig): Promise<BuildResult> {
  const errors: string[] = [];
  const engine = await createEngine(config.templateDir);
  const pages: Page[] = [];

  // Read all markdown files
  for await (const filePath of walkDir(config.sourceDir)) {
    if (extname(filePath) !== ".md") continue;

    try {
      const raw = await readFile(filePath, "utf-8");
      const { frontmatter, body } = parseFrontmatter(raw);
      const htmlContent = markdownToHtml(body);
      const url = pathToUrl(filePath, config.sourceDir);

      pages.push({
        path: filePath,
        sourcePath: relative(config.sourceDir, filePath),
        frontmatter,
        content: body,
        html: htmlContent,
        url,
      });
    } catch (err) {
      errors.push(`Error processing ${filePath}: ${String(err)}`);
    }
  }

  // Sort by date descending
  pages.sort((a, b) => {
    const da = a.frontmatter.date ?? "";
    const db = b.frontmatter.date ?? "";
    return db.localeCompare(da);
  });

  // Build tag indexes
  const tags = buildTagIndexes(pages);

  // Load templates
  let pageTemplate = "";
  let indexTemplate = "";
  let tagTemplate = "";
  try {
    pageTemplate = await readFile(join(config.templateDir, "post.hbs"), "utf-8");
  } catch {
    // Template optional
  }
  try {
    indexTemplate = await readFile(join(config.templateDir, "index.hbs"), "utf-8");
  } catch {
    // Template optional
  }
  try {
    tagTemplate = await readFile(join(config.templateDir, "tag.hbs"), "utf-8");
  } catch {
    // Template optional
  }

  // Render page files
  for (const page of pages) {
    if (page.frontmatter.draft) continue;

    const template = page.frontmatter.layout
      ? await loadTemplate(config.templateDir, page.frontmatter.layout)
      : pageTemplate;

    if (!template) continue;

    const html = engine.renderPage(
      template,
      {
        page,
        pages,
        tags,
        config,
        title: page.frontmatter.title,
        date: page.frontmatter.date,
        content: page.html,
      },
      page.frontmatter.layout ? undefined : undefined
    );

    const outPath = join(config.outputDir, page.url === "/" ? "index.html" : page.url + "index.html");
    await writeTextFile(outPath, html);
  }

  // Render index page
  if (indexTemplate) {
    const publicPages = pages.filter(p => !p.frontmatter.draft);
    const indexHtml = engine.renderPage(indexTemplate, {
      pages: publicPages,
      tags,
      config,
      title: config.siteTitle,
    });
    await writeTextFile(join(config.outputDir, "index.html"), indexHtml);
  }

  // Render tag pages
  if (tagTemplate) {
    for (const tagIndex of tags) {
      const tagHtml = engine.renderPage(tagTemplate, {
        tag: tagIndex,
        pages: tagIndex.pages,
        tags,
        config,
        title: `Tag: ${tagIndex.tag}`,
      });
      await writeTextFile(
        join(config.outputDir, "tags", tagIndex.tag, "index.html"),
        tagHtml
      );
    }
  }

  // RSS feed
  const rss = generateRss(pages, config);
  await writeTextFile(join(config.outputDir, "feed.xml"), rss);

  // Copy static assets (non-.md files)
  for await (const filePath of walkDir(config.sourceDir)) {
    if (extname(filePath) === ".md") continue;
    const rel = relative(config.sourceDir, filePath);
    const dest = join(config.outputDir, rel);
    await writeTextFile(dest, await readFile(filePath, "utf-8"));
  }

  return { pages, tags, errors };
}

async function loadTemplate(templateDir: string, name: string): Promise<string> {
  try {
    return await readFile(join(templateDir, `${name}.hbs`), "utf-8");
  } catch {
    return "";
  }
}

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import { watch } from "chokidar";
import type { SiteConfig } from "./types.js";
import { build } from "./build.js";

const RELOAD_SCRIPT = `
<script>
(function(){
  var ws = new WebSocket('ws://' + location.host + '/__ssg_reload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      window.location.reload();
    }, 1000);
  };
})();
</script>
`;

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".xml": "application/xml",
  ".ico": "image/x-icon",
};

function injectReload(body: string): string {
  if (body.includes("</body>")) {
    return body.replace("</body>", RELOAD_SCRIPT + "</body>");
  }
  return body + RELOAD_SCRIPT;
}

export async function startServer(
  config: SiteConfig,
  port: number = 3000,
  sourceDir?: string,
  templateDir?: string
): Promise<void> {
  let wss: WebSocketServer;

  const server = createServer((req: IncomingMessage, res: ServerResponse) => {
    const url = req.url ?? "/";
    let filePath = join(config.outputDir, url === "/" ? "index.html" : url);

    // Fallback for clean URLs
    if (!existsSync(filePath) || filePath.endsWith("/")) {
      const htmlPath = join(filePath, "index.html");
      if (existsSync(htmlPath)) {
        filePath = htmlPath;
      }
    }

    const ext = extname(filePath);
    const mime = MIME[ext] || "application/octet-stream";

    try {
      let body = readFileSync(filePath, "utf-8");
      if (mime.startsWith("text/html")) {
        body = injectReload(body);
      }
      res.writeHead(200, { "Content-Type": mime });
      res.end(body);
    } catch {
      res.writeHead(404, { "Content-Type": "text/plain" });
      res.end("Not found");
    }
  });

  wss = new WebSocketServer({ server });

  let clients: WebSocket[] = [];
  wss.on("connection", (ws) => {
    clients.push(ws);
    ws.on("close", () => {
      clients = clients.filter(c => c !== ws);
    });
  });

  function reloadAll() {
    for (const client of clients) {
      try { client.send("reload"); } catch { /* ignore */ }
    }
  }

  // Watch source and template dirs
  const watchDirs: string[] = [sourceDir ?? config.sourceDir];
  if (templateDir ?? config.templateDir) {
    watchDirs.push(templateDir ?? config.templateDir);
  }

  const watcher = watch(watchDirs, {
    ignored: /(^|[/\\])\../, // dotfiles
    persistent: true,
  });

  let rebuildTimer: ReturnType<typeof setTimeout> | null = null;
  const scheduleRebuild = () => {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(async () => {
      try {
        await build(config);
        reloadAll();
      } catch (err) {
        console.error("Rebuild error:", err);
      }
    }, 150);
  };

  watcher.on("change", scheduleRebuild);
  watcher.on("add", scheduleRebuild);
  watcher.on("unlink", scheduleRebuild);

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
    console.log(`Live reload enabled`);
  });
}

#!/usr/bin/env node
import { Command } from "commander";
import { resolve } from "node:path";
import type { SiteConfig } from "./types.js";
import { build } from "./build.js";
import { startServer } from "./server.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator")
  .version("1.0.0");

program
  .command("build")
  .description("Build the static site")
  .requiredOption("-s, --source <dir>", "Source directory of markdown files")
  .requiredOption("-t, --templates <dir>", "Template directory of Handlebars files")
  .requiredOption("-o, --output <dir>", "Output directory for generated HTML")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-url <url>", "Site URL for RSS", "http://localhost:3000")
  .action(async (opts) => {
    const config: SiteConfig = {
      sourceDir: resolve(opts.source),
      templateDir: resolve(opts.templates),
      outputDir: resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
    };

    console.log(`Building site from ${config.sourceDir}...`);
    const result = await build(config);
    console.log(`Built ${result.pages.length} pages, ${result.tags.length} tag indexes.`);
    if (result.errors.length > 0) {
      console.error("Errors:");
      for (const err of result.errors) {
        console.error(`  - ${err}`);
      }
    }
  });

program
  .command("serve")
  .description("Start dev server with live reload")
  .requiredOption("-s, --source <dir>", "Source directory of markdown files")
  .requiredOption("-t, --templates <dir>", "Template directory of Handlebars files")
  .requiredOption("-o, --output <dir>", "Output directory for generated HTML")
  .option("-p, --port <port>", "Port to listen on", "3000")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-url <url>", "Site URL for RSS", "http://localhost:3000")
  .action(async (opts) => {
    const config: SiteConfig = {
      sourceDir: resolve(opts.source),
      templateDir: resolve(opts.templates),
      outputDir: resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
    };

    // Initial build
    console.log("Building site...");
    await build(config);

    const port = parseInt(opts.port, 10);
    await startServer(config, port, opts.source, opts.templates);
  });

program.parse();

