import { describe, it, expect } from "vitest";
import { parseFrontmatter } from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("parses YAML frontmatter between --- delimiters", () => {
    const input = `---
title: Test Post
date: 2024-01-15
tags:
  - js
  - css
draft: false
---
# Hello

Content here.`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Test Post");
    expect(result.frontmatter.date).toBe("2024-01-15");
    expect(result.frontmatter.tags).toEqual(["js", "css"]);
    expect(result.frontmatter.draft).toBe(false);
    expect(result.body).toContain("# Hello");
    expect(result.body).toContain("Content here.");
  });

  it("returns default title when no frontmatter", () => {
    const input = "# Just markdown\n\nNo frontmatter here.";
    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
    expect(result.body).toBe(input);
  });

  it("handles missing closing delimiter gracefully", () => {
    const input = `---
title: Incomplete
# Content`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
  });

  it("normalizes tags to lowercase trimmed strings", () => {
    const input = `---
title: Tag Test
tags:
  -  JavaScript
  - "  TypeScript  "
  - CSS
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.tags).toEqual(["javascript", "typescript", "css"]);
  });

  it("handles non-array tags by wrapping in array", () => {
    const input = `---
title: Single Tag
tags: javascript
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.tags).toEqual(["javascript"]);
  });

  it("sets default title when title is missing in frontmatter", () => {
    const input = `---
date: 2024-01-01
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
    expect(result.frontmatter.date).toBe("2024-01-01");
  });

  it("handles empty frontmatter block", () => {
    const input = `---
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
    expect(result.body).toBe("Body");
  });

  it("handles empty body after frontmatter", () => {
    const input = `---
title: Only Meta
---`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Only Meta");
    expect(result.body).toBe("");
  });

  it("handles malformed YAML gracefully", () => {
    const input = `---
title: Broken
{{{invalid
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
    expect(result.body).toBe("Body");
  });

  it("handles empty object YAML", () => {
    const input = `---
{}
---
Body`;

    const result = parseFrontmatter(input);
    expect(result.frontmatter.title).toBe("Untitled");
  });

  it("preserves body content exactly", () => {
    const input = `---
title: Preserve
---
Line 1
Line 2

Line 3`;

    const result = parseFrontmatter(input);
    expect(result.body).toBe("Line 1\nLine 2\n\nLine 3");
  });
});

import { describe, it, expect } from "vitest";
import { createTestEngine } from "../src/templates.js";

describe("TemplateEngine", () => {
  const engine = createTestEngine(
    { header: "<nav>Nav</nav>", footer: "<footer>Foot</footer>" },
    "<html><body>{{{body}}}</body></html>"
  );

  it("renders a simple template with data", () => {
    const result = engine.render("<h1>{{title}}</h1>", { title: "Hello" });
    expect(result).toBe("<h1>Hello</h1>");
  });

  it("renders a template with partials", () => {
    const result = engine.render(
      "<div>{{> header}}<p>Body</p>{{> footer}}</div>",
      {}
    );
    expect(result).toContain("<nav>Nav</nav>");
    expect(result).toContain("<footer>Foot</footer>");
    expect(result).toContain("<p>Body</p>");
  });

  it("renderPage wraps content in layout", () => {
    const result = engine.renderPage(
      "<h1>{{title}}</h1>",
      { title: "My Page" }
    );
    expect(result).toContain("<html>");
    expect(result).toContain("<h1>My Page</h1>");
    expect(result).toContain("</body></html>");
  });

  it("renderPage uses provided layout override", () => {
    const result = engine.renderPage(
      "content",
      {},
      "<div>{{{body}}}</div>"
    );
    expect(result).toBe("<div>content</div>");
  });

  it("renderPage without layout returns body only", () => {
    const e = createTestEngine();
    const result = e.renderPage("<p>Raw</p>", {});
    expect(result).toBe("<p>Raw</p>");
  });

  it("handles HTML in data without escaping", () => {
    const result = engine.render("<div>{{{content}}}</div>", {
      content: "<strong>Bold</strong>",
    });
    expect(result).toBe("<div><strong>Bold</strong></div>");
  });

  it("supports each/if helpers", () => {
    const result = engine.render(
      "{{#each items}}<li>{{this}}</li>{{/each}}",
      { items: ["a", "b"] }
    );
    expect(result).toBe("<li>a</li><li>b</li>");
  });

  it("supports nested object access", () => {
    const result = engine.render("<p>{{page.frontmatter.title}}</p>", {
      page: { frontmatter: { title: "Nested" } },
    });
    expect(result).toBe("<p>Nested</p>");
  });
});

import { describe, it, expect, afterEach } from "vitest";
import { readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { build } from "../src/build.js";
import type { SiteConfig } from "../src/types.js";

const outputDir = join(__dirname, "fixtures", "output");
const sourceDir = join(__dirname, "fixtures", "posts");
const templateDir = join(__dirname, "fixtures", "templates");

const config: SiteConfig = {
  sourceDir,
  templateDir,
  outputDir,
  siteTitle: "Test Site",
  siteUrl: "http://localhost:3000",
};

afterEach(async () => {
  await rm(outputDir, { recursive: true, force: true });
});

describe("CLI build", () => {
  it("builds HTML pages from markdown files", async () => {
    const result = await build(config);
    expect(result.errors).toEqual([]);
    expect(result.pages.length).toBe(3);

    const helloHtml = await readFile(
      join(outputDir, "hello", "index.html"),
      "utf-8"
    );
    expect(helloHtml).toContain("Hello World");
    expect(helloHtml).toContain('class="hljs');
    expect(helloHtml).toContain("console");
  });

  it("skips draft posts", async () => {
    const result = await build(config);
    const draftExists = await fileExists(
      join(outputDir, "draft", "index.html")
    );
    expect(draftExists).toBe(false);

    const indexHtml = await readFile(
      join(outputDir, "index.html"),
      "utf-8"
    );
    expect(indexHtml).not.toContain("Secret Draft");
    expect(indexHtml).toContain("Hello World");
  });

