      join(outputDir, "tags", "javascript", "index.html"),
      "utf-8"
    );
    expect(jsHtml).toContain("Tag: javascript");
    expect(jsHtml).toContain("Hello World");
  });

  it("generates RSS feed", async () => {
    await build(config);

    const rss = await readFile(join(outputDir, "feed.xml"), "utf-8");
    expect(rss).toContain("<rss version=\"2.0\"");
    expect(rss).toContain("<title>Test Site</title>");
    expect(rss).toContain("<title>Hello World</title>");
    expect(rss).toContain("<title>Second Post</title>");
    expect(rss).not.toContain("Secret Draft");
  });

  it("uses layout template with partials", async () => {
    await build(config);

    const helloHtml = await readFile(
      join(outputDir, "hello", "index.html"),
      "utf-8"
    );
    expect(helloHtml).toContain("<!DOCTYPE html>");
    expect(helloHtml).toContain("<nav>My Site Navigation</nav>");
    expect(helloHtml).toContain("<time>2024-01-15</time>");
  });
});

async function fileExists(path: string): Promise<boolean> {
  try {
    await readFile(path);
    return true;
  } catch {
    return false;
  }
}

import { describe, it, expect } from "vitest";
import { buildTagIndexes } from "../src/tags.js";
import type { Page } from "../src/types.js";

function makePage(title: string, date: string, tags: string[], draft = false): Page {
  return {
    path: `/posts/${title.toLowerCase()}.md`,
    sourcePath: `${title.toLowerCase()}.md`,
    frontmatter: { title, date, tags, draft },
    content: "",
    html: "",
    url: `/${title.toLowerCase()}/`,
  };
}

describe("buildTagIndexes", () => {
  it("groups pages by tag", () => {
    const pages = [
      makePage("A", "2024-01-01", ["js", "css"]),
      makePage("B", "2024-02-01", ["js"]),
      makePage("C", "2024-03-01", ["css"]),
    ];

    const indexes = buildTagIndexes(pages);
    expect(indexes.length).toBe(2);
    expect(indexes[0].tag).toBe("css");
    expect(indexes[1].tag).toBe("js");
    expect(indexes[0].pages.length).toBe(2);
    expect(indexes[1].pages.length).toBe(2);
  });

  it("excludes draft pages", () => {
    const pages = [
      makePage("A", "2024-01-01", ["js"]),
      makePage("B", "2024-02-01", ["js"], true),
    ];

    const indexes = buildTagIndexes(pages);
    expect(indexes[0].pages.length).toBe(1);
    expect(indexes[0].pages[0].frontmatter.title).toBe("A");
  });

  it("handles pages without tags", () => {
    const pages = [
      makePage("A", "2024-01-01", []),
      makePage("B", "2024-02-01", ["js"]),
    ];

    const indexes = buildTagIndexes(pages);
    expect(indexes.length).toBe(1);
    expect(indexes[0].tag).toBe("js");
  });

  it("sorts pages by date descending within each tag", () => {
    const pages = [
      makePage("Old", "2024-01-01", ["js"]),
      makePage("New", "2024-06-01", ["js"]),
    ];

    const indexes = buildTagIndexes(pages);
    expect(indexes[0].pages[0].frontmatter.title).toBe("New");
    expect(indexes[0].pages[1].frontmatter.title).toBe("Old");
  });

  it("returns empty array for no tagged pages", () => {
    const pages = [makePage("A", "2024-01-01", [])];
    expect(buildTagIndexes(pages)).toEqual([]);
  });
});

import { describe, it, expect } from "vitest";
import { generateRss } from "../src/rss.js";
import type { Page, SiteConfig } from "../src/types.js";

function makePage(title: string, date: string, draft = false): Page {
  return {
    path: `/posts/${title.toLowerCase()}.md`,
    sourcePath: `${title.toLowerCase()}.md`,
    frontmatter: { title, date, tags: [] },
    content: "",
    html: "",
    url: `/${title.toLowerCase()}/`,
  };
}

const config: SiteConfig = {
  sourceDir: "/src",
  templateDir: "/tmpl",
  outputDir: "/out",
  siteTitle: "My Blog",
  siteUrl: "https://example.com",
};

describe("generateRss", () => {
  it("generates valid RSS XML", () => {
    const pages = [makePage("Post One", "2024-01-15")];
    const rss = generateRss(pages, config);

    expect(rss).toContain('<?xml version="1.0" encoding="UTF-8"?>');
    expect(rss).toContain('<rss version="2.0"');
    expect(rss).toContain("<title>My Blog</title>");
    expect(rss).toContain("<title>Post One</title>");
  });

  it("orders by date descending", () => {
    const pages = [
      makePage("Old", "2024-01-01"),
      makePage("New", "2024-06-15"),
    ];

    const rss = generateRss(pages, config);
    const newIdx = rss.indexOf("<title>New</title>");
    const oldIdx = rss.indexOf("<title>Old</title>");
    expect(newIdx).toBeLessThan(oldIdx);
  });

  it("excludes draft posts", () => {
    const pages = [
      makePage("Public", "2024-01-01"),
      { ...makePage("Draft", "2024-02-01"), frontmatter: { title: "Draft", date: "2024-02-01", tags: [], draft: true } },
    ];

    const rss = generateRss(pages, config);
    expect(rss).toContain("Public");
    expect(rss).not.toContain("Draft");
  });

  it("excludes posts without dates", () => {
    const pages = [
      { ...makePage("No Date", ""), frontmatter: { title: "No Date", tags: [] } },
      makePage("Has Date", "2024-01-01"),
    ];

    const rss = generateRss(pages, config);
    expect(rss).toContain("Has Date");
    expect(rss).not.toContain("No Date");
  });

  it("escapes XML special characters", () => {
    const pages = [
      {
        ...makePage("A & B", "2024-01-01"),
        frontmatter: { title: "Title <b> & \"quotes\"", date: "2024-01-01", tags: [] },
      },
    ];

    const rss = generateRss(pages, config);
    expect(rss).toContain("Title &lt;b&gt; &amp; &quot;quotes&quot;");
  });

  it("limits to 20 items", () => {
    const pages = Array.from({ length: 25 }, (_, i) =>
      makePage(`Post ${i}`, `2024-${String(i + 1).padStart(2, "0")}-01`)
    );

    const rss = generateRss(pages, config);
    const itemCount = (rss.match(/<item>/g) || []).length;
    expect(itemCount).toBe(20);
  });
});

import { describe, it, expect } from "vitest";
import { markdownToHtml } from "../src/markdown.js";

describe("markdownToHtml", () => {
  it("converts basic markdown to HTML", () => {
    const result = markdownToHtml("# Hello\n\nWorld");
    expect(result).toContain("<h1>Hello</h1>");
    expect(result).toContain("<p>World</p>");
  });

  it("highlights code blocks with syntax", () => {
    const result = markdownToHtml('```js\nconst x = 1;\n```');
    expect(result).toContain("hljs");
    expect(result).toContain("language-js");
    expect(result).toContain("const");
  });

  it("handles auto-detection for unknown languages", () => {
    const result = markdownToHtml('```\nconst x = 1;\n```');
    expect(result).toContain("<code>");
  });

  it("handles GFM tables", () => {
    const result = markdownToHtml("| a | b |\n|---|---|\n| 1 | 2 |");
    expect(result).toContain("<table>");
    expect(result).toContain("<td>1</td>");
  });

  it("handles inline code", () => {
    const result = markdownToHtml("Use `const` keyword");
    expect(result).toContain("<code>const</code>");
  });

  it("returns empty string for non-string input via async guard", () => {
    // marked.parse can return string | Promise; our wrapper handles this
    const result = markdownToHtml("");
    expect(result).toBe("");
  });
});

import { describe, it, expect } from "vitest";
import { slugify, pathToUrl, formatDate, parseDate } from "../src/utils.js";

describe("utils", () => {
  describe("slugify", () => {
    it("converts text to lowercase slug", () => {
      expect(slugify("Hello World")).toBe("hello-world");
    });

    it("removes special characters", () => {
      expect(slugify("Foo & Bar!")).toBe("foo-bar");
    });

    it("trims dashes from edges", () => {
      expect(slugify("--hello--")).toBe("hello");
    });
  });

  describe("pathToUrl", () => {
    it("converts file paths to clean URLs", () => {
      expect(pathToUrl("/src/posts/hello.md", "/src")).toBe("/hello/");
    });

    it("handles index.md as root", () => {
      expect(pathToUrl("/src/index.md", "/src")).toBe("/");
    });
  });

  describe("formatDate", () => {
    it("formats date as YYYY-MM-DD", () => {
      expect(formatDate(new Date("2024-01-15"))).toBe("2024-01-15");
    });
  });

  describe("parseDate", () => {
    it("parses valid date strings", () => {
      const d = parseDate("2024-01-15");
      expect(d.getFullYear()).toBe(2024);
    });

    it("throws on invalid date", () => {
      expect(() => parseDate("not a date")).toThrow("Invalid date");
    });
  });
});

